<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security {
    function parse_url(string $url): array|false
    {
        if (($GLOBALS['__test_parse_url_force_false'] ?? false) === true) {
            return false;
        }

        return \parse_url($url);
    }
}

namespace {
    use PHPUnit\Framework\TestCase;
    use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
    use Psr\SimpleCache\CacheInterface;
    use Psr\Http\Message\ServerRequestInterface;
    use Psr\Http\Message\UriInterface;
    use Civi\Lughauth\Shared\Security\MagicLinkService;
    use Civi\Lughauth\Shared\Security\Identity;
    use Civi\Lughauth\Shared\Security\Connection;
    use Civi\Lughauth\Shared\AppConfig;

    #[AllowMockObjectsWithoutExpectations]
    final class MagicLinkServiceUnitTest extends TestCase
    {
        protected function setUp(): void
        {
            unset($GLOBALS['__test_parse_url_force_false']);
        }

        public function testCreateRequiresTokenOrIdentity(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache);

            $this->expectException(\InvalidArgumentException::class);
            $service->create('https://example.org/callback', null, null, null, null);
        }

        public function testCreateWithRequestStoresAuthorizationHeader(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache, [
                'security.magiclink.param' => 'ml',
                'security.magiclink.ttl' => 'PT5M',
                'security.magiclink.reads' => 2,
            ]);
            $request = $this->request(
                queryParams: [],
                path: '/callback',
                query: '',
                headers: ['Authorization' => ['Bearer abc']]
            );

            $url = 'https://example.org/callback?foo=bar';
            $full = $service->create($url, $request);

            $token = $this->extractTokenFromUrl($full, 'ml');
            $this->assertNotSame('', $token);

            $cacheKey = 'magic_link_' . $token;
            $this->assertTrue($cache->has($cacheKey));

            $payload = json_decode((string) $cache->get($cacheKey), true);
            $this->assertSame('/callback?foo=bar', $payload['path']);
            $this->assertSame('Bearer abc', $payload['token']);
            $this->assertNull($payload['identity']);
            $this->assertNull($payload['connection']);
            $this->assertSame(0, $payload['reads']);
            $this->assertSame(2, $payload['max']);

            $query = (string) parse_url($full, PHP_URL_QUERY);
            $params = [];
            parse_str($query, $params);
            $this->assertSame('bar', $params['foo'] ?? null);
            $this->assertSame($token, $params['ml'] ?? null);
        }

        public function testCreateWithIdentityAndConnectionSerializesPayload(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache, [
                'security.magiclink.param' => 'ml',
                'security.magiclink.reads' => 3,
            ]);
            $identity = Identity::from(
                anonymous: false,
                authScope: Identity::AUTH_SCOPE_READ,
                id: 'user-1',
                name: 'User 1',
                token: 'id-token',
                issuer: 'issuer',
                tenant: 'tenant',
                roles: ['role-a'],
                groups: ['group-a'],
                claims: ['k' => 'v'],
                scope: 'scope-a',
                email: 'user@example.org'
            );
            $connection = new Connection(
                level: 1,
                remote: true,
                startTime: new \DateTime('2024-01-01T00:00:00+00:00'),
                application: 'app',
                callback: '/callback',
                source: '192.168.1.1',
                target: 'example.org',
                locale: 'en'
            );

            $full = $service->create('https://example.org/callback', null, 'jwt', $identity, $connection);
            $token = $this->extractTokenFromUrl($full, 'ml');
            $cacheKey = 'magic_link_' . $token;
            $payload = json_decode((string) $cache->get($cacheKey), true);

            $this->assertSame('jwt', $payload['token']);
            $this->assertSame('user-1', $payload['identity']['id']);
            $this->assertSame('app', $payload['connection']['application']);
        }

        public function testCreateNormalizesEmptyPathToSlash(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache, ['security.magiclink.param' => 'ml']);

            $url = 'https://example.org';
            $full = $service->create($url, null, 'jwt');
            $token = $this->extractTokenFromUrl($full, 'ml');
            $cacheKey = 'magic_link_' . $token;
            $payload = json_decode((string) $cache->get($cacheKey), true);

            $this->assertSame('/', $payload['path']);
        }

        public function testCreateWithParseUrlFailureFallsBackToRawUrl(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache, ['security.magiclink.param' => 'ml']);
            $GLOBALS['__test_parse_url_force_false'] = true;

            $url = 'https://example.org/callback?foo=bar';
            $full = $service->create($url, null, 'jwt');
            $token = $this->extractTokenFromUrl($full, 'ml');
            $cacheKey = 'magic_link_' . $token;
            $payload = json_decode((string) $cache->get($cacheKey), true);

            $this->assertSame($url, $payload['path']);
            $this->assertStringContainsString('ml=' . $token, $full);
        }

        public function testConsumeReturnsNullWhenTokenMissing(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache);

            $request = $this->request([]);
            $this->assertNull($service->consume($request));
        }

