        public function testConsumeDeletesWhenReadLimitReached(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache, ['security.magiclink.param' => 'ml']);

            $cacheKey = 'magic_link_token';
            $cache->set($cacheKey, json_encode([
                'path' => '/callback',
                'token' => 'jwt',
                'identity' => [
                    'anonymous' => false,
                    'authScope' => Identity::AUTH_SCOPE_BOTH,
                    'id' => 'user',
                    'name' => 'User',
                    'token' => null,
                    'issuer' => null,
                    'tenant' => null,
                    'roles' => ['admin'],
                    'groups' => ['group'],
                    'claims' => ['k' => 'v'],
                    'scope' => 'scope',
                    'email' => 'user@example.org',
                ],
                'connection' => [
                    'level' => 2,
                    'remote' => true,
                    'startTime' => '2024-01-01T00:00:00+00:00',
                    'application' => 'app',
                    'callback' => '/callback',
                    'source' => '10.0.0.1',
                    'target' => 'example.org',
                    'locale' => 'en',
                ],
                'reads' => 0,
                'max' => 1,
            ]));

            $request = $this->request(['ml' => 'token'], '/callback', 'ml=token');
            $result = $service->consume($request);

            $this->assertIsArray($result);
            $this->assertSame('jwt', $result['token']);
            $this->assertInstanceOf(Identity::class, $result['identity']);
            $this->assertInstanceOf(Connection::class, $result['connection']);
            $this->assertFalse($cache->has($cacheKey));
        }

        public function testConsumePersistsWhenReadLimitNotReached(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache, ['security.magiclink.param' => 'ml']);

            $cacheKey = 'magic_link_token';
            $cache->set($cacheKey, json_encode([
                'path' => '/callback',
                'token' => 'jwt',
                'connection' => [
                    'level' => 0,
                    'remote' => true,
                    'application' => 'app',
                    'callback' => '/callback',
                    'source' => '10.0.0.2',
                    'target' => 'example.org',
                    'locale' => 'en',
                ],
                'reads' => 0,
                'max' => 2,
            ]));

            $request = $this->request(['ml' => 'token'], '/callback', 'ml=token');
            $result = $service->consume($request);

            $this->assertIsArray($result);
            $this->assertSame('jwt', $result['token']);
            $this->assertInstanceOf(Connection::class, $result['connection']);
            $this->assertTrue($cache->has($cacheKey));

            $payload = json_decode((string) $cache->get($cacheKey), true);
            $this->assertSame(1, $payload['reads']);
        }

