        public function testConsumeNormalizesEmptyPathAndRemovesTokenParam(): void
        {
            $cache = new MagicLinkArrayCache();
            $service = $this->serviceWithConfig($cache, ['security.magiclink.param' => 'ml']);

            $cacheKey = 'magic_link_token';
            $cache->set($cacheKey, json_encode([
                'path' => '/?foo=bar',
                'token' => 'jwt',
                'reads' => 0,
                'max' => 1,
            ]));

            $request = $this->request(['ml' => 'token'], '', 'ml=token&foo=bar');
            $result = $service->consume($request);

            $this->assertIsArray($result);
            $this->assertSame('jwt', $result['token']);
        }

        private function serviceWithConfig(MagicLinkArrayCache $cache, array $config = []): MagicLinkService
        {
            $configMock = $this->createMock(AppConfig::class);
            $configMock->method('get')->willReturnCallback(function (string $key, $default) use ($config) {
                return $config[$key] ?? $default;
            });

            return new MagicLinkService($cache, $configMock);
        }

        private function request(
            array $queryParams,
            string $path = '/callback',
            string $query = '',
            array $headers = []
        ): ServerRequestInterface {
            $request = $this->createMock(ServerRequestInterface::class);
            $uri = $this->createMock(UriInterface::class);
            $uri->method('getPath')->willReturn($path);
            $uri->method('getQuery')->willReturn($query);
            $request->method('getUri')->willReturn($uri);
            $request->method('getQueryParams')->willReturn($queryParams);
            $request->method('getHeader')->willReturnCallback(function (string $name) use ($headers) {
                return $headers[$name] ?? [];
            });

            return $request;
        }

        private function extractTokenFromUrl(string $url, string $paramName): string
        {
            $query = (string) parse_url($url, PHP_URL_QUERY);
            $params = [];
            parse_str($query, $params);

            return (string) ($params[$paramName] ?? '');
        }
    }

    final class MagicLinkArrayCache implements CacheInterface
    {
        public array $store = [];
        public array $ttls = [];

        public function get(string $key, mixed $default = null): mixed
        {
            return $this->store[$key] ?? $default;
        }

        public function set(string $key, mixed $value, null|int|\DateInterval $ttl = null): bool
        {
            $this->store[$key] = $value;
            $this->ttls[$key] = $ttl;
            return true;
        }

        public function delete(string $key): bool
        {
            unset($this->store[$key], $this->ttls[$key]);
            return true;
        }

        public function clear(): bool
        {
            $this->store = [];
            $this->ttls = [];
            return true;
        }

        public function getMultiple(iterable $keys, mixed $default = null): iterable
        {
            $values = [];
            foreach ($keys as $key) {
                $values[$key] = $this->get($key, $default);
            }
            return $values;
        }

        public function setMultiple(iterable $values, null|int|\DateInterval $ttl = null): bool
        {
            foreach ($values as $key => $value) {
                $this->set($key, $value, $ttl);
            }
            return true;
        }

        public function deleteMultiple(iterable $keys): bool
        {
            foreach ($keys as $key) {
                $this->delete($key);
            }
            return true;
        }

        public function has(string $key): bool
        {
            return array_key_exists($key, $this->store);
        }
    }
}
